/**
 * ProveOutPromotionEngine — Promote prove-out programs to production
 *
 * Takes a prove-out G-code program (generated by ProveOutModeEngine) and strips
 * all prove-out modifications to produce a production-ready program:
 *   - Removes PROVE-OUT comment lines
 *   - Removes M01 optional stops added during prove-out
 *   - Removes single-block header comments
 *   - Restores original feed rates (by reversing the derating)
 *   - Restores original RPM values (by reversing the cap)
 *   - Generates A/B comparison between prove-out and production
 *   - Includes operator sign-off block
 *
 * References:
 *   - Peter Smid, "CNC Programming Handbook" 3rd ed., Ch. 28 (First Article)
 *   - PRISM ProveOutModeEngine (upstream engine)
 *
 * @module engines/ProveOutPromotionEngine
 * @version 1.0.0
 */

// ─── Types ──────────────────────────────────────────────────────────

export interface PromotionInput {
  /** Prove-out G-code program to promote */
  prove_out_gcode: string;
  /** Original G-code (pre-prove-out) for comparison. If not provided, restoration is heuristic. */
  original_gcode?: string;
  /** Feed reduction factor used during prove-out (0-1). Used to restore feeds if original not provided. */
  feed_reduction?: number;
  /** RPM cap factor used during prove-out (0-1). Used to restore RPMs if original not provided. */
  rpm_cap?: number;
  /** Operator name for sign-off */
  operator_name?: string;
  /** Part number for sign-off */
  part_number?: string;
  /** Job/work order number for sign-off */
  job_number?: string;
  /** Include operator sign-off block in output */
  include_sign_off?: boolean;
}

export interface PromotionDiffLine {
  line_number: number;
  prove_out: string;
  production: string;
  change_type: "removed" | "restored_feed" | "restored_rpm" | "restored_both" | "unchanged";
}

export interface PromotionResult {
  /** Production-ready G-code */
  production_gcode: string;
  /** A/B comparison diff */
  diff: PromotionDiffLine[];
  /** Summary statistics */
  summary: {
    total_lines_prove_out: number;
    total_lines_production: number;
    lines_removed: number;
    feeds_restored: number;
    rpms_restored: number;
    m01_removed: number;
    comments_removed: number;
    header_lines_removed: number;
  };
  /** Operator sign-off block (if requested) */
  sign_off?: {
    operator: string;
    part_number: string;
    job_number: string;
    date: string;
    status: "pending" | "approved" | "rejected";
    notes: string;
  };
  /** Whether promotion used original G-code (exact) or heuristic restoration */
  restoration_method: "exact" | "heuristic";
  /** Warnings about the promotion */
  warnings: string[];
}

// ─── Patterns ───────────────────────────────────────────────────────

const PROVE_OUT_HEADER_PATTERN = /PROVE-OUT MODE.*FIRST ARTICLE|RECOMMEND:.*SINGLE-BLOCK|FEEDS REDUCED.*RPM CAPPED|OPTIONAL STOPS AT CRITICAL/i;
const PROVE_OUT_COMMENT_PATTERN = /PROVE-OUT:|FIRST ARTICLE|OPTIONAL STOP FOR PROVE-OUT/i;
const M01_PATTERN = /^\s*M0?1\s*$/;
const FEED_REGEX = /F([\d.]+)/;
const RPM_REGEX = /S([\d.]+)/;
const SPINDLE_DIR_REGEX = /M0?[34]\b/;

/**
 * Extract feed reduction factor from prove-out header.
 * Parses "FEEDS REDUCED 25% | RPM CAPPED 80%" pattern.
 */
function parseHeaderReduction(gcode: string): { feed_reduction: number; rpm_cap: number } | null {
  const match = gcode.match(/FEEDS REDUCED (\d+)%.*RPM CAPPED (\d+)%/i);
  if (!match) return null;
  return {
    feed_reduction: parseInt(match[1], 10) / 100,
    rpm_cap: parseInt(match[2], 10) / 100,
  };
}

// ─── Engine ─────────────────────────────────────────────────────────

class ProveOutPromotionEngineImpl {
  /**
   * Promote a prove-out program to production.
   *
   * If `original_gcode` is provided, uses it as the exact restoration target.
   * Otherwise, uses the feed_reduction/rpm_cap factors to reverse the derating.
   *
   * @param input - Promotion configuration
   * @returns Promotion result with production G-code, diff, and summary
   */
  promote(input: PromotionInput): PromotionResult {
    const proveOutLines = input.prove_out_gcode.split("\n");
    const warnings: string[] = [];
    const diff: PromotionDiffLine[] = [];

    // Determine restoration method
    const hasOriginal = !!input.original_gcode;
    const headerParams = parseHeaderReduction(input.prove_out_gcode);

    // Feed/RPM restoration factors
    const feedReduction = input.feed_reduction ?? headerParams?.feed_reduction ?? 0.25;
    const rpmCap = input.rpm_cap ?? headerParams?.rpm_cap ?? 0.80;

    if (!hasOriginal && !headerParams && input.feed_reduction === undefined) {
      warnings.push("No original G-code and no feed_reduction provided — using default 25% feed restoration");
    }

    let linesRemoved = 0;
    let feedsRestored = 0;
    let rpmsRestored = 0;
    let m01Removed = 0;
    let commentsRemoved = 0;
    let headerRemoved = 0;
    let prodLineNum = 0;

    if (hasOriginal) {
      // Exact restoration: use original G-code as production output
      return this.exactRestore(input, proveOutLines);
    }

    // Heuristic restoration: reverse the derating mathematically
    const productionLines: string[] = [];

    for (let i = 0; i < proveOutLines.length; i++) {
      const line = proveOutLines[i];
      const trimmed = line.trim();

      // Remove prove-out header lines
      if (PROVE_OUT_HEADER_PATTERN.test(trimmed)) {
        diff.push({ line_number: i + 1, prove_out: line, production: "", change_type: "removed" });
        headerRemoved++;
        linesRemoved++;
        continue;
      }

      // Remove prove-out comment lines
      if (PROVE_OUT_COMMENT_PATTERN.test(trimmed)) {
        diff.push({ line_number: i + 1, prove_out: line, production: "", change_type: "removed" });
        commentsRemoved++;
        linesRemoved++;
        continue;
      }

      // Remove M01 optional stops (but not M00 programmed stops)
      if (M01_PATTERN.test(trimmed)) {
        diff.push({ line_number: i + 1, prove_out: line, production: "", change_type: "removed" });
        m01Removed++;
        linesRemoved++;
        continue;
      }

      // Restore feed rates
      let restoredLine = line;
      let feedChanged = false;
      let rpmChanged = false;

      const feedMatch = restoredLine.match(FEED_REGEX);
      if (feedMatch && feedReduction > 0 && feedReduction < 1) {
        const derated = parseFloat(feedMatch[1]);
        const original = Math.round(derated / (1 - feedReduction));
        if (original !== derated) {
          restoredLine = restoredLine.replace(FEED_REGEX, `F${original}`);
          feedChanged = true;
          feedsRestored++;
        }
      }

      // Restore RPM values
      const rpmMatch = restoredLine.match(RPM_REGEX);
      if (rpmMatch && rpmCap > 0 && rpmCap < 1 && SPINDLE_DIR_REGEX.test(trimmed)) {
        const capped = parseFloat(rpmMatch[1]);
        const original = Math.round(capped / rpmCap);
        if (original !== capped) {
          restoredLine = restoredLine.replace(RPM_REGEX, `S${original}`);
          rpmChanged = true;
          rpmsRestored++;
        }
      }

      prodLineNum++;
      productionLines.push(restoredLine);

      const changeType = feedChanged && rpmChanged ? "restored_both" :
                          feedChanged ? "restored_feed" :
                          rpmChanged ? "restored_rpm" : "unchanged";

      if (changeType !== "unchanged") {
        diff.push({ line_number: i + 1, prove_out: line, production: restoredLine, change_type: changeType });
      }
    }

    const productionGcode = productionLines.join("\n");

    // Validate restored values
    const feedValues = productionGcode.match(/F([\d.]+)/g);
    if (feedValues) {
      for (const fv of feedValues) {
        const f = parseFloat(fv.slice(1));
        if (f > 50000) warnings.push(`Restored feed ${f} mm/min seems high — verify original program`);
        if (f <= 0) warnings.push(`Restored feed ${f} mm/min is invalid`);
      }
    }

    const result: PromotionResult = {
      production_gcode: productionGcode,
      diff,
      summary: {
        total_lines_prove_out: proveOutLines.length,
        total_lines_production: productionLines.length,
        lines_removed: linesRemoved,
        feeds_restored: feedsRestored,
        rpms_restored: rpmsRestored,
        m01_removed: m01Removed,
        comments_removed: commentsRemoved,
        header_lines_removed: headerRemoved,
      },
      restoration_method: "heuristic",
      warnings,
    };

    if (input.include_sign_off !== false) {
      result.sign_off = {
        operator: input.operator_name ?? "",
        part_number: input.part_number ?? "",
        job_number: input.job_number ?? "",
        date: new Date().toISOString().split("T")[0],
        status: "pending",
        notes: "",
      };
    }

    return result;
  }

  /**
   * Exact restoration using original G-code.
   * Generates detailed diff between prove-out and original.
   */
  private exactRestore(input: PromotionInput, proveOutLines: string[]): PromotionResult {
    const originalLines = input.original_gcode!.split("\n");
    const diff: PromotionDiffLine[] = [];
    const warnings: string[] = [];

    let linesRemoved = 0;
    let feedsRestored = 0;
    let rpmsRestored = 0;
    let m01Removed = 0;
    let commentsRemoved = 0;
    let headerRemoved = 0;

    // Build diff — match prove-out lines to original lines
    let origIdx = 0;
    for (let i = 0; i < proveOutLines.length; i++) {
      const poLine = proveOutLines[i].trim();

      // Header/comment/M01 lines don't exist in original
      if (PROVE_OUT_HEADER_PATTERN.test(poLine)) {
        diff.push({ line_number: i + 1, prove_out: proveOutLines[i], production: "", change_type: "removed" });
        headerRemoved++;
        linesRemoved++;
        continue;
      }
      if (PROVE_OUT_COMMENT_PATTERN.test(poLine)) {
        diff.push({ line_number: i + 1, prove_out: proveOutLines[i], production: "", change_type: "removed" });
        commentsRemoved++;
        linesRemoved++;
        continue;
      }
      if (M01_PATTERN.test(poLine)) {
        diff.push({ line_number: i + 1, prove_out: proveOutLines[i], production: "", change_type: "removed" });
        m01Removed++;
        linesRemoved++;
        continue;
      }

      // Match to original line
      if (origIdx < originalLines.length) {
        const origLine = originalLines[origIdx];
        const feedDiff = this.hasFeedDiff(proveOutLines[i], origLine);
        const rpmDiff = this.hasRpmDiff(proveOutLines[i], origLine);

        const changeType = feedDiff && rpmDiff ? "restored_both" :
                           feedDiff ? "restored_feed" :
                           rpmDiff ? "restored_rpm" : "unchanged";

        if (feedDiff) feedsRestored++;
        if (rpmDiff) rpmsRestored++;

        if (changeType !== "unchanged") {
          diff.push({ line_number: i + 1, prove_out: proveOutLines[i], production: origLine, change_type: changeType });
        }
        origIdx++;
      }
    }

    if (origIdx < originalLines.length) {
      warnings.push(`Original has ${originalLines.length - origIdx} more lines than prove-out mappable lines`);
    }

    const result: PromotionResult = {
      production_gcode: input.original_gcode!,
      diff,
      summary: {
        total_lines_prove_out: proveOutLines.length,
        total_lines_production: originalLines.length,
        lines_removed: linesRemoved,
        feeds_restored: feedsRestored,
        rpms_restored: rpmsRestored,
        m01_removed: m01Removed,
        comments_removed: commentsRemoved,
        header_lines_removed: headerRemoved,
      },
      restoration_method: "exact",
      warnings,
    };

    if (input.include_sign_off !== false) {
      result.sign_off = {
        operator: input.operator_name ?? "",
        part_number: input.part_number ?? "",
        job_number: input.job_number ?? "",
        date: new Date().toISOString().split("T")[0],
        status: "pending",
        notes: "",
      };
    }

    return result;
  }

  private hasFeedDiff(a: string, b: string): boolean {
    const fa = a.match(FEED_REGEX);
    const fb = b.match(FEED_REGEX);
    if (!fa || !fb) return false;
    return fa[1] !== fb[1];
  }

  private hasRpmDiff(a: string, b: string): boolean {
    const sa = a.match(RPM_REGEX);
    const sb = b.match(RPM_REGEX);
    if (!sa || !sb) return false;
    return sa[1] !== sb[1];
  }
}

/** Singleton export */
export const proveOutPromotionEngine = new ProveOutPromotionEngineImpl();
